"""Checked partial assembly of cached original-span surfaces.

The accepted complete path is retained verbatim. The fallback keeps only
providers with valid geometry records, while requiring the complete original
identity/ownership registry. It does not fabricate a mouth, relax a check, or
draw a strip across a failed patch. Separator identity remains mandatory while
an unavailable opening or invalid fill suppresses only that separator.
"""
import bpy
from . import curved_junction_nodes as boundary, curved_network_surface_nodes as network
from . import curved_compound_network_nodes as compounds, curved_logical_network_nodes as logical
from . import curved_patch_provider_nodes as patches, curved_strip_provider_nodes as strips
from . import curved_network_ownership_nodes as ownership
c = boundary.c


def _ready(g, status, identity, at):
    found, row = patches._lookup(g, status, identity, at)
    return found * c._read(g, status, 'valid', row, 'BOOLEAN')


def _faces(g, geometry, selection):
    node = g.node('GeometryNodeSeparateGeometry', 'Keep only a valid provider surface')
    node.domain = 'FACE'
    g.bind(geometry, node.inputs['Geometry']); g.bind(selection, node.inputs['Selection'])
    return node.outputs['Selection']


def _seam_references(g, geometry, mouths, active):
    """Keep face-free matching rows only while an accepted strip uses them.

    Face-domain filtering discards the reference row of a matching two-Street
    seam. It is required by the exact identity weld even though the row itself
    has no pavement faces. Do not retain it when neither incident strip survives.
    """
    mid = c.named(g, 'st_cn_mouth', 'INT')
    peer = c._read(g, mouths, 'st_cj_seam_peer', mid, 'INT')
    linked = 0.
    for rows, fields in ((active[0], ('st_cs_start_index', 'st_cs_end_index')),
                        (active[1], ('st_ca_start_index',))):
        for field in fields:
            for endpoint in (mid, peer):
                found, _ = patches._lookup(g, rows, field, endpoint)
                linked = g.math('MAXIMUM', linked, found)
    neighbors = g.node('GeometryNodeInputMeshVertexNeighbors')
    loose = ownership._compare(g, neighbors.outputs['Vertex Count'], 0)
    valid = ownership._compare(g, mid, 0, 'GREATER_EQUAL')
    valid = valid*c._read(g, mouths, 'st_cj_seam', mid, 'BOOLEAN')
    valid = valid*c._read(g, mouths, 'st_cj_valid', mid, 'BOOLEAN')
    return c._select(g, geometry, loose*valid*linked)


def _source_location(g, inp, incidence):
    approaches, mapping = inp.outputs['Approaches'], inp.outputs['Mapping']
    span = c._read(g, approaches, 'st_pp_span', incidence, 'INT')
    reverse = c._read(g, approaches, 'st_pp_reverse', incidence, 'INT')
    knot = c.choose(g, reverse, c._read(g, mapping, 'st_ps_last', span, 'INT'),
                    c._read(g, mapping, 'st_ps_first', span, 'INT'), 'INT')
    start = c._read(g, mapping, 'st_ps_start', span, 'INT')
    return c._sample(g, inp.outputs['Sources'], g.position(), start+knot, 'FLOAT_VECTOR')


def _failure_records(g, inp, status, kind):
    """Private mesh points carry live locations and durable owner identities."""
    if kind == 0:
        at = c.named(g, patches.SITE, 'INT')
        incidence = c._read(g, inp.outputs['Junctions'], 'st_cj_range_start', at, 'INT')
        section = -1
        junction = c.named(g, 'st_cn_owner', 'INT')
        code = 20
    else:
        at = c.named(g, strips.INDEX, 'INT')
        table, prefix = ('Corridors', 'st_cs_') if kind == 1 else ('External Approaches', 'st_ca_')
        incidence = c._read(g, inp.outputs[table], prefix+'start_index', at, 'INT')
        span = c._read(g, inp.outputs['Approaches'], 'st_pp_span', incidence, 'INT')
        first = c._read(g, inp.outputs['Mapping'], 'st_ps_edge_start', span, 'INT')
        first = first+c._read(g, inp.outputs['Mapping'], 'st_ps_first', span, 'INT')
        section = boundary._edge_sample(g, inp.outputs['Sources'], c.named(g, 'st_section_id', 'INT'), first, 'INT')
        junction = -1
        code = c.choose(g, c.named(g, 'inputs_valid', 'BOOLEAN'), 5, 1, 'INT')
    result = g.setpos(status, _source_location(g, inp, incidence))
    for name, value in (('st_diagnostic_code', code), ('st_section_id', section),
                        ('st_intersection_id', junction), ('st_bundle_id', -1)):
        result = c._store(g, result, name, value, 'INT')
    return c._select(g, result, 1.-c.named(g, 'valid', 'BOOLEAN'))


def partial(g, inp, *, free_ended_separators=False, chained_separators=False, free_chained_separators=False, crossing_separator_regions=False, longitudinal_separator_chains=False):
    index = c.V(g, g.node('GeometryNodeInputIndex').outputs[0])
    registry = g.node('GeometryNodeGroup', 'Original ownership remains mandatory during a local failure')
    registry.node_tree = compounds.registry(port_paths=True)
    for key in ('Approaches', 'Junctions', 'Compounds'):g.bind(inp.outputs[key], registry.inputs[key])
    original, logical_valid = logical.registry(g, inp, registry.outputs['Approaches'])
    guard = g.node('GeometryNodeGroup'); guard.node_tree = ownership.build(port_paths=True)
    for key, value in (('Approaches', original), ('Corridors', inp.outputs['Corridors']),
                       ('External Approaches', inp.outputs['External Approaches'])):
        g.bind(value, guard.inputs[key])
    patch, patch_identity = patches.unpack(g, inp, original)
    corridor, approach, strip_identity = strips.unpack(g, inp, require_geometry_valid=False)
    n = c._count(g, inp.outputs['Junctions'])
    structural = c.V(g, registry.outputs['Valid'])*logical_valid*c.V(g, guard.outputs['Valid'])
    structural = structural*patch_identity*strip_identity
    # This branch consumes independently evaluated providers, not the bounded
    # monolithic patch repeat. Exact transport counts below bound ownership.
    structural = structural*g.math('GREATER_THAN', n, .5)
    expected = n-c._count(g, inp.outputs['Compounds'])
    expected = expected-c._count(g, inp.outputs['Cluster Sites'])+c._count(g, inp.outputs['Logical Clusters'])
    structural = structural*ownership._compare(g, c._count(g, patch.outputs['Status']), expected)
    before = g.node('GeometryNodeAccumulateField'); before.data_type='INT'; before.domain='POINT'
    g.bind(c.named(g, 'st_cj_range_count', 'INT'), before.inputs['Value'])
    structural = structural*c._stat(g, inp.outputs['Junctions'],
        ownership._compare(g, c.named(g, 'st_cj_range_start', 'INT'), before.outputs['Trailing']))
    order = g.node('GeometryNodeSortElements'); order.domain='POINT'
    g.bind(patch.outputs['Mouths'], order.inputs['Geometry'])
    g.bind(c.named(g, 'st_cj_input_index', 'INT'), order.inputs['Sort Weight'])
    mouths = order.outputs['Geometry']
    structural = structural*ownership._compare(g, c._count(g, mouths), c._count(g, original))
    structural = structural*c._stat(g, mouths, ownership._compare(g, c.named(g, 'st_cj_input_index', 'INT'), index))
    for table, fields in ((inp.outputs['Corridors'], ('st_cs_start_index', 'st_cs_end_index')),
                           (inp.outputs['External Approaches'], ('st_ca_start_index',))):
        for field in fields:
            check = 1.-c._read(g, original, 'st_cn_absorbed', c.named(g, field, 'INT'), 'BOOLEAN')
            structural = structural*c.choose(g, g.math('GREATER_THAN', c._count(g, table), .5), c._stat(g, table, check), 1.)

    patch_mesh = _faces(g, patch.outputs['Patches'],
        _ready(g, patch.outputs['Status'], patches.SITE, c.named(g, '_cn_face_owner', 'INT')))
    surfaces = []
    active = []
    failures = [_failure_records(g, inp, patch.outputs['Status'], 0)]
    for part, table_name, kind in ((corridor, 'Corridors', 1), (approach, 'External Approaches', 3)):
        surfaces.append(_faces(g, part.outputs['Surfaces'],
            _ready(g, part.outputs['Status'], strips.INDEX, c.named(g, '_cn_face_owner', 'INT'))))
        active.append(c._select(g, inp.outputs[table_name], _ready(g, part.outputs['Status'], strips.INDEX, index)))
        failures.append(_failure_records(g, inp, part.outputs['Status'], kind))
    patch_mesh = boundary._join(g, patch_mesh,
        _seam_references(g, patch.outputs['Patches'], mouths, active))
    surface = boundary._join(g, *surfaces)
    mesh, agreement, matched, oriented, profiles, cells, identities, _ = network.assemble_surfaces(
        g, patch_mesh, surface, mouths, active[0], external_rows=active[1], local_frames=True)
    drawable = structural*c.V(g, agreement)*matched*oriented*profiles*cells*identities
    drawable = drawable*g.math('GREATER_THAN', c._count(g, mesh), 0.)
    if 'Separators' in inp.outputs:
        from . import curved_separator_network_nodes, curved_separator_contract_nodes
        separator_identity = curved_separator_contract_nodes.registry(g, inp, original, patch.outputs['Status'],
            free_ends=free_ended_separators,chained=chained_separators,free_chains=free_chained_separators,regions=crossing_separator_regions,
            longitudinal_chains=longitudinal_separator_chains)
        structural = structural*separator_identity
        drawable = drawable*separator_identity
        fill = g.node('GeometryNodeGroup', 'Retain checked separators with complete ownership declarations')
        if free_ended_separators:
            from . import curved_separator_dispatch_nodes
            fill.node_tree = curved_separator_dispatch_nodes.build(retain_failures=True,chained=chained_separators,
                                                                  free_chains=free_chained_separators,regions=crossing_separator_regions,
                                                                  longitudinal_chains=longitudinal_separator_chains)
            g.bind(inp.outputs['External Approaches'], fill.inputs['External Approaches'])
            if chained_separators:g.bind(inp.outputs['Separator Owners'],fill.inputs['Separator Owners'])
        else: fill.node_tree = curved_separator_network_nodes.build(unequal_caps=True, retain_failures=True)
        for key, value in (('Pavement', boundary._empty(g, mesh, drawable)), ('Corridors', inp.outputs['Corridors']),
                           ('Mouths', mouths), ('Separators', inp.outputs['Separators']),
                           ('Expected Count', inp.outputs['Separator Count']), ('Cell Size', inp.outputs['Cell Size']),
                           ('Grass', inp.outputs['Grass'])):
            g.bind(value, fill.inputs[key])
        mesh = fill.outputs['Geometry']; drawable = drawable*c.V(g, fill.outputs['Output Valid'])
        failed = c._select(g, fill.outputs['Status'], 1.-c.named(g, 'st_separator_valid', 'BOOLEAN'))
        row = c.named(g, 'st_separator_index', 'INT')
        # Source location is derived from the declared terminal owner,
        # which remains available even when both corridor surfaces failed.
        head = c._read(g, inp.outputs['Separators'], 'st_sb_head_patch', row, 'INT')
        incidence = c._read(g, inp.outputs['Junctions'], 'st_cj_range_start', head, 'INT')
        failed = g.setpos(failed, _source_location(g, inp, incidence))
        for key, value in (('st_cn_kind', 4), ('st_cn_owner', c.named(g, 'st_bundle_id', 'INT')),
                           ('st_diagnostic_code', 7), ('st_section_id', -1), ('st_intersection_id', -1)):
            failed = c._store(g, failed, key, value, 'INT')
        failures.append(failed)
    status = c._line(g, 1)
    for name, value in (('st_partial_output_valid', drawable), ('st_partial_identity_valid', structural),
                        ('st_partial_profiles_valid', profiles), ('st_partial_seams_valid', matched),
                        ('st_partial_cells_valid', cells), ('st_partial_oriented', oriented)):
        status = c._store(g, status, name, value, 'BOOLEAN')
    failures = boundary._join(g, *failures)
    local_records = structural*g.math('GREATER_THAN', c._count(g, failures), .5)
    # The absence of drawable pavement must not suppress its explanation. A
    # broken registry or assembly gets a network-level record at the controller
    # origin; do not invent a Section location from untrusted owner lookups.
    global_record = c._line(g, 1)
    for key, value in (('st_diagnostic_code', 32), ('st_section_id', -1),
                       ('st_intersection_id', -1), ('st_bundle_id', -1),
                       ('st_cn_kind', -1), ('st_cn_owner', -1)):
        global_record = c._store(g, global_record, key, value, 'INT')
    failures = c.choose(g, local_records, failures, global_record, 'GEOMETRY')
    return boundary._empty(g, mesh, drawable), drawable, failures, status


def construction_identity(strict_core):
    """One cache identity shared by source construction and saved migrations."""
    name = 'Prochitecture Streets / Original local failure assembly candidate v6'
    for key,label in (
        ('st_free_ended_separators',' / Free-ended separators v1'),
        ('st_chained_separators',' / Chained separators v1'),
        ('st_free_chained_separators',' / Free chained separators v1'),
        ('st_longitudinal_separator_chains',' / Original multi-Street side ownership v1'),
        ('st_crossing_separator_regions',' / Crossing regions v1')):
        if strict_core.get(key):name+=label
    import hashlib
    construction=name+' / Core '+strict_core.name
    return ('Prochitecture Streets / Original local failure assembly candidate v6 / '+
            hashlib.sha256(construction.encode('utf8')).hexdigest()[:16],construction)


def build(strict_core):
    """One common assembly with explicit complete versus safe partial status."""
    free_ended = bool(strict_core.get('st_free_ended_separators'))
    chained = bool(strict_core.get('st_chained_separators'))
    free_chained = bool(strict_core.get('st_free_chained_separators'))
    longitudinal = bool(strict_core.get('st_longitudinal_separator_chains'))
    regions = bool(strict_core.get('st_crossing_separator_regions'))
    # Exact/Smooth and other strict-core variants can share all separator
    # flags. Include the wrapped core identity so one cannot silently reuse
    # a wrapper whose accepted branch points at a different solver.
    name,construction=construction_identity(strict_core)
    if name in bpy.data.node_groups:return bpy.data.node_groups[name]
    g = c.Graph(name)
    g.g['st_construction_label']=construction
    if longitudinal:g.g['st_longitudinal_separator_chains']=1
    inputs = [s for s in strict_core.interface.items_tree if s.item_type=='SOCKET' and s.in_out=='INPUT']
    outputs = [s for s in strict_core.interface.items_tree if s.item_type=='SOCKET' and s.in_out=='OUTPUT']
    for socket in inputs:
        g.socket(socket.name, socket.socket_type, default=getattr(socket, 'default_value', None))
    for socket in outputs:g.socket(socket.name, socket.socket_type, 'OUTPUT')
    for key, kind in (('Output Valid', 'NodeSocketBool'), ('Failure Records', 'NodeSocketGeometry'),
                       ('Partial Status', 'NodeSocketGeometry')):g.socket(key, kind, 'OUTPUT')
    inp = g.node('NodeGroupInput'); out = g.node('NodeGroupOutput')
    complete = g.node('GeometryNodeGroup', 'Keep the accepted complete construction verbatim')
    complete.node_tree = strict_core
    for socket in inputs:g.bind(inp.outputs[socket.name], complete.inputs[socket.name])
    mesh, safe, failures, status = partial(g, inp, free_ended_separators=free_ended,chained_separators=chained,
                                         free_chained_separators=free_chained,crossing_separator_regions=regions,
                                         longitudinal_separator_chains=longitudinal)
    points = g.node('GeometryNodeMeshToPoints', 'Generated failure records, separate from pavement mesh')
    points.mode = 'VERTICES'; g.bind(failures, points.inputs['Mesh'])
    # Object Info can consume the evaluated point-cloud component without
    # rerunning a second network solver. to_mesh still sees pavement only.
    diagnosed_mesh = boundary._join(g, mesh, points.outputs['Points'])
    good = complete.outputs['Valid']
    for socket in outputs:
        value = complete.outputs[socket.name]
        if socket.name=='Geometry':value = c.choose(g, good, value, diagnosed_mesh, 'GEOMETRY')
        g.bind(value, out.inputs[socket.name])
    g.bind(c.choose(g, good, True, safe, 'BOOLEAN'), out.inputs['Output Valid'])
    g.bind(boundary._empty(g, failures, 1.-c.V(g, good)), out.inputs['Failure Records'])
    g.bind(status, out.inputs['Partial Status'])
    return g.g
